sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (newValue == '') {
		g_form.setValue('table_name', '-- None --');
        return;
    }

    var tablename = g_form.getValue('table_name');

    // Clear all of the choices from the What needed field choice list
    g_form.clearOptions('table_name');

    // If the value of the Request type field is hr, add
    // two hr choices and other to the What needed field choice list
    if (newValue == 'hr') {
        g_form.addOption('table_name', 'hr1', 'Human Resources 1');
        g_form.addOption('table_name', 'hr2', 'Human Resources 2');
        g_form.addOption('table_name', 'other', 'Other');
    }
    // If the value of the Request type field is facilities, add
    // two facilities choices and other to the What needed field
    // choice list
    if (newValue == 'sd1') {
        g_form.addOption('table_name', 'sd11', 'SD1 Table1');
        g_form.addOption('table_name', 'sd12', 'SD1 Table2');
        g_form.addOption('table_name', 'sd13', 'SD1 Table3');
    }
    // If the value of the Request type field is legal, add
    // two legal choices and other to the What needed field
    // choice list
    if (newValue == 'sd2') {
        g_form.addOption('table_name', 'sd21', 'SD2 Table1');
        g_form.addOption('table_name', 'sd22', 'SD2 Table2');
        g_form.addOption('table_name', 'sd23', 'SD2 Table3');
        g_form.addOption('table_name', 'sd24', 'SD2 Table4');
    }

    // If the form is loading and it is not a new record, set the table_name value to the
    // value from the record before it was loaded
    if (isLoading && !g_form.isNewRecord()) {
        g_form.setValue('table_name', tablename);
    }
}
